    return '<section class="az-visual-band az-visual-home"><div class="az-wrap"><div class="az-section-heading"><p class="az-kicker az-dark"><span></span> EXPERIENCE THE DIFFERENCE</p><h2>Comfort you can feel.<br>Control you can trust.</h2></div><div class="az-premium-gallery"><article class="az-photo az-img-home"><div><small>CONNECTED LIVING</small><h3>Your whole home in one touch.</h3></div></article><article class="az-photo az-img-theatre"><div><small>IMMERSIVE AV</small><h3>Every seat becomes the best seat.</h3></div></article><article class="az-photo az-img-cctv"><div><small>SMART SECURITY</small><h3>Awareness, even when you are away.</h3></div></article></div></div></section>';
}

